#!/usr/bin/env python3
"""Build the numeric ground truth for CSX-054_Q2 from local CSX-054 files."""

from __future__ import annotations

import datetime as dt
import json
from pathlib import Path
from typing import Any, Iterable, Iterator


TASK_ID = "CSX-054_Q2"
TASK_DIR = Path(__file__).resolve().parent
REPO_ROOT = TASK_DIR.parents[2]
PACKAGE_DIR = REPO_ROOT / "event_packages" / "standard_event_packages" / "packages" / "CSX-054"

SOURCE_FILES = [
    "metadata/event.json",
    "data/event_reports/event_reports_003_Locked_event_anchor_2024_Sudan_floods_and_Arba_at_Dam_flood.json",
    "data/physical_hazard/physical_hazard_002_ERA5-Land_hourly_aggregate_stats.json",
    "data/physical_hazard/physical_hazard_004_GPM_IMERG_V07_event_accumulated_precipitation.json",
    "data/physical_hazard/physical_hazard_006_CHIRPS_daily_event_accumulated_precipitation.json",
    "data/exposure_impact/exposure_impact_003_WorldPop_GP_100m_population_sum.json",
    "data/exposure_impact/exposure_impact_005_OpenStreetMap_Overpass_bounded_AOI_slice.json",
    "data/remote_sensing/remote_sensing_005_Sentinel-1_GRD_VV_pre_post_change.json",
    "data/remote_sensing/remote_sensing_003_Google_Satellite_Embedding_annual_cosine-change_stats.json",
    "data/remote_sensing/remote_sensing_007_pre.jpg",
    "data/remote_sensing/remote_sensing_008_event.jpg",
]



DEEPENED_TASK_FRAME = {'bounded_prompt': 'The task diagnoses flood pressure and process, not exact inundation depth, building damage, or '
                   'final loss totals.',
 'decisive_evidence_prompt': 'Rainfall concentration and areal or urban-response evidence should dominate; exposure '
                             'and image products are supporting context.',
 'group': 'deepened_remaining_39',
 'mechanism_chain': ['rainfall burst or accumulation',
                     'duration/intensity or areal-load calculation',
                     'urban runoff or receptor context',
                     'single-number simplification rejection'],
 'mechanism_question': 'reconstruct how rainfall concentration translates into pluvial or urban runoff pressure rather '
                       'than a generic wet-period label',
 'new_title': 'Heavy Rainfall With Weak Mean Surface-Change Diagnosis',
 'rejected_prompt': 'Reject a one-gauge, one-hour, exposure-only, or image-primary explanation if the computed '
                    'rainfall-runoff chain is stronger.',
 'target_family': 'rainfall_concentration_surface_proxy_weighting_diagnosis',
 'task_mode': 'deep_mechanism_diagnosis'}

def _deep_rename_key(key):
    replacements = [
        ("score_ledger", "evidence_rows"),
        ("ledger_rows", "evidence_rows"),
        ("ledger", "evidence_synthesis"),
        ("Ledger", "EvidenceSynthesis"),
        ("consistency", "process_alignment"),
        ("Consistency", "ProcessAlignment"),
        ("threshold", "diagnostic_gate"),
        ("Threshold", "DiagnosticGate"),
        ("gate", "diagnostic_test"),
        ("Gate", "DiagnosticTest"),
        ("score_breakdown", "evidence_score_breakdown"),
        ("score", "evidence_score"),
        ("Score", "EvidenceScore"),
    ]
    out = str(key)
    for old, new in replacements:
        out = out.replace(old, new)
    return out


def _deep_rename_obj(value, parent_key=None):
    protected_value_keys = {
        "answer",
        "final_label",
        "classification",
        "label",
        "diagnosis",
        "result",
        "answer_type",
        "task_family",
        "target_family",
    }
    if isinstance(value, dict):
        return {_deep_rename_key(k): _deep_rename_obj(v, k) for k, v in value.items()}
    if isinstance(value, list):
        return [_deep_rename_obj(v, parent_key) for v in value]
    if isinstance(value, str):
        if parent_key in protected_value_keys:
            return value
        out = value
        replacements = [
            ("ledger", "evidence synthesis"),
            ("Ledger", "Evidence synthesis"),
            ("consistency", "process alignment"),
            ("Consistency", "Process alignment"),
            ("threshold", "diagnostic gate"),
            ("Threshold", "Diagnostic gate"),
        ]
        for old, new in replacements:
            out = out.replace(old, new)
        return out
    return value

def _deep_extract_answer(value):
    if isinstance(value, dict):
        for key in ("final_label", "answer", "classification", "label", "final_interpretation", "diagnosis"):
            if key in value and isinstance(value[key], (str, int, float, bool)):
                return str(value[key])
        for key in ("classification", "threshold_result", "result"):
            if key in value and isinstance(value[key], dict):
                nested = _deep_extract_answer(value[key])
                if nested:
                    return nested
    return "deep_mechanism_diagnosis"


def apply_deepened_task_frame(result):
    frame = dict(DEEPENED_TASK_FRAME)
    old_primary = result.get("primary_gt")
    if not isinstance(old_primary, dict):
        old_primary = {"value": old_primary}
    transformed = {
        "answer": frame.get("answer_override", _deep_extract_answer(old_primary)),
        "task_mode": frame["task_mode"],
        "mechanism_question": frame["mechanism_question"],
        "computed_evidence": _deep_rename_obj(old_primary),
        "mechanism_chain": list(frame["mechanism_chain"]),
        "decisive_evidence": frame["decisive_evidence_prompt"],
        "rejected_simplifications": frame["rejected_prompt"],
        "bounded_interpretation": frame["bounded_prompt"],
    }
    if frame.get("formula_prompt"):
        transformed["formula_derivation"] = frame["formula_prompt"]
    if isinstance(transformed.get("computed_evidence"), dict):
        for stale_key in ("answer", "answer_type", "target_family", "task_family"):
            transformed["computed_evidence"].pop(stale_key, None)
    result["primary_gt"] = transformed
    result["task_type"] = "structured_reasoning"
    result["evaluation_mode"] = "hybrid"
    result["subtype"] = frame["task_mode"]
    result["target_family"] = frame.get("target_family", frame["task_mode"])
    result["deepened_reframe"] = {
        "group": frame["group"],
        "replaces_table_only_task": True,
        "new_title": frame["new_title"],
    }
    guidance = result.get("answer_guidance")
    if isinstance(guidance, dict):
        guidance["structured_answer"] = transformed
        guidance["answer"] = transformed["answer"]
    else:
        result["answer_guidance"] = {"structured_answer": transformed, "answer": transformed["answer"]}
    result["rubric"] = {
        "total_points": 20,
        "criteria": [
            {"name": "mechanism_diagnosis", "points": 4, "description": "Identifies the dominant physical process and gives the correct compact answer label or an equivalent diagnosis."},
            {"name": "computed_evidence", "points": 5, "description": "Recomputes the quantitative evidence inherited from the original task and preserves units, signs, ratios, and key values."},
            {"name": "evidence_weighting", "points": 4, "description": "Explains which evidence streams are decisive and which are contextual or weaker proxies."},
            {"name": "counterfactual_rejection", "points": 3, "description": "Rejects at least one tempting simplified explanation using the computed values rather than assertion."},
            {"name": "bounded_interpretation", "points": 2, "description": "States scale, timing, proxy, or uncertainty limits without adding unsupported losses or impacts."},
            {"name": "json_contract", "points": 2, "description": "Returns the requested structured mechanism-diagnosis JSON without reducing the answer to a row-only table or same-scale checklist."},
        ],
    }
    if frame.get("formula_prompt"):
        result["rubric"] = {
            "total_points": 20,
            "criteria": [
                {"name": "mechanism_diagnosis", "points": 3, "description": "Identifies the dominant physical process and gives the correct compact mechanism label or equivalent diagnosis."},
                {"name": "computed_evidence", "points": 4, "description": "Recomputes the package-derived quantitative evidence with correct units, signs, ratios, dates, and rounding."},
                {"name": "formula_derivation", "points": 3, "description": "Shows the requested physical formula, scaling relation, or timing relation and connects it to the computed values."},
                {"name": "evidence_weighting", "points": 3, "description": "Explains which evidence streams are decisive and which are contextual or weaker proxies."},
                {"name": "counterfactual_rejection", "points": 3, "description": "Rejects tempting simplified explanations using computed values rather than assertion."},
                {"name": "bounded_interpretation", "points": 2, "description": "States scale, timing, proxy, or uncertainty limits without adding unsupported losses or impacts."},
                {"name": "json_contract", "points": 2, "description": "Returns the requested structured mechanism-diagnosis JSON without reducing the answer to a row-only table."},
            ],
        }

    return result

def load_json(rel_path: str) -> Any:
    with (PACKAGE_DIR / rel_path).open("r", encoding="utf-8-sig") as f:
        return json.load(f)


def nested(d: dict[str, Any], *keys: str, default: Any = None) -> Any:
    cur: Any = d
    for key in keys:
        if not isinstance(cur, dict) or key not in cur:
            return default
        cur = cur[key]
    return cur


def osm_receptor_slice_path() -> str:
    exposure_dir = PACKAGE_DIR / "data" / "exposure_impact"
    matches = sorted(exposure_dir.glob("exposure_impact_005_OpenStreetMap_Overpass_bounded_*_slice.json"))
    if not matches:
        raise FileNotFoundError("OpenStreetMap receptor slice not found")
    return matches[0].relative_to(PACKAGE_DIR).as_posix()


def duration_days(start: str, end: str) -> int:
    return (dt.date.fromisoformat(end) - dt.date.fromisoformat(start)).days + 1


def count_osm(rel_path: str) -> dict[str, Any]:
    data = load_json(rel_path)
    elements = data.get("elements", []) if isinstance(data, dict) else []
    highway_count = 0
    critical_amenity_count = 0
    amenity_counts: dict[str, int] = {}
    for element in elements:
        tags = element.get("tags", {}) if isinstance(element, dict) else {}
        if not isinstance(tags, dict):
            continue
        if "highway" in tags:
            highway_count += 1
        amenity = tags.get("amenity")
        if amenity:
            name = str(amenity)
            amenity_counts[name] = amenity_counts.get(name, 0) + 1
            if name in {"hospital", "clinic", "fire_station", "police", "school", "shelter"}:
                critical_amenity_count += 1
    return {
        "element_count": len(elements),
        "highway_count": highway_count,
        "critical_amenity_count": critical_amenity_count,
        "amenity_counts": dict(sorted(amenity_counts.items())),
    }


def pixel_triplets(pixel_source: Any) -> Iterator[tuple[int, int, int]]:
    if hasattr(pixel_source, "get_flattened_data"):
        raw_pixels: Iterable[Any] = pixel_source.get_flattened_data()
    elif hasattr(pixel_source, "getdata"):
        raw_pixels = pixel_source.getdata()
    else:
        raw_pixels = pixel_source

    pixels = list(raw_pixels)
    if not pixels:
        return

    first = pixels[0]
    if isinstance(first, (tuple, list)):
        for pixel in pixels:
            if len(pixel) >= 3:
                yield int(pixel[0]), int(pixel[1]), int(pixel[2])
        return

    for i in range(0, len(pixels) - 2, 3):
        yield int(pixels[i]), int(pixels[i + 1]), int(pixels[i + 2])


def image_metrics(rel_path: str) -> dict[str, Any]:
    path = PACKAGE_DIR / rel_path
    try:
        from PIL import Image

        with Image.open(path) as img:
            original_width, original_height = img.width, img.height
            rgb = img.convert("RGB").resize((256, 192))
            pixels = list(pixel_triplets(rgb))
        n = len(pixels)
        mean_r = sum(p[0] for p in pixels) / n
        mean_g = sum(p[1] for p in pixels) / n
        mean_b = sum(p[2] for p in pixels) / n
        dark_share = sum(1 for r, g, b in pixels if (r + g + b) / 3 < 55) / n
        blue_dark_share = sum(1 for r, g, b in pixels if b > r + 10 and b > g and (r + g + b) / 3 < 95) / n
        return {
            "available": True,
            "width": original_width,
            "height": original_height,
            "mean_rgb": [round(mean_r, 2), round(mean_g, 2), round(mean_b, 2)],
            "dark_pixel_share": round(dark_share, 4),
            "dark_blue_proxy_share": round(blue_dark_share, 4),
        }
    except Exception:
        return {"available": path.is_file(), "width": None, "height": None}


def build_result() -> dict[str, Any]:
    event = load_json("metadata/event.json")
    anchor = load_json("data/event_reports/event_reports_003_Locked_event_anchor_2024_Sudan_floods_and_Arba_at_Dam_flood.json")
    era5 = load_json("data/physical_hazard/physical_hazard_002_ERA5-Land_hourly_aggregate_stats.json")
    gpm = load_json("data/physical_hazard/physical_hazard_004_GPM_IMERG_V07_event_accumulated_precipitation.json")
    chirps = load_json("data/physical_hazard/physical_hazard_006_CHIRPS_daily_event_accumulated_precipitation.json")
    worldpop = load_json("data/exposure_impact/exposure_impact_003_WorldPop_GP_100m_population_sum.json")
    osm = count_osm(osm_receptor_slice_path())
    sentinel1 = load_json("data/remote_sensing/remote_sensing_005_Sentinel-1_GRD_VV_pre_post_change.json")
    alphaearth = load_json("data/remote_sensing/remote_sensing_003_Google_Satellite_Embedding_annual_cosine-change_stats.json")

    start = nested(anchor, "temporal_window", "start_date")
    end = nested(anchor, "temporal_window", "end_date")
    days = duration_days(start, end)

    maxima = {
        "era5_land": float(era5["stats"]["precipitation_sum_mm_max"]),
        "gpm": float(gpm["stats"]["gpm_event_precip_mm_max"]),
        "chirps": float(chirps["stats"]["chirps_event_precip_mm_max"]),
    }
    means = {
        "era5_land": float(era5["stats"]["precipitation_sum_mm_mean"]),
        "gpm": float(gpm["stats"]["gpm_event_precip_mm_mean"]),
        "chirps": float(chirps["stats"]["chirps_event_precip_mm_mean"]),
    }
    ratios = {name: maxima[name] / means[name] for name in maxima}
    strongest_product = max(ratios, key=ratios.get)
    max_product = max(maxima, key=maxima.get)
    products_ge_150 = sum(1 for value in maxima.values() if value >= 150.0)
    rain_threshold_pass = products_ge_150 == 3 and maxima[max_product] >= 200.0
    concentration_pass = ratios[strongest_product] >= 3.0
    three_product_mean = sum(means.values()) / len(means)

    pre_image = image_metrics("data/remote_sensing/remote_sensing_007_pre.jpg")
    event_image = image_metrics("data/remote_sensing/remote_sensing_008_event.jpg")
    dark_blue_pp = round((event_image["dark_blue_proxy_share"] - pre_image["dark_blue_proxy_share"]) * 100, 2)
    s1_mean = round(float(nested(sentinel1, "stats", "s1_vv_post_minus_pre_db_mean")), 3)
    s1_min = round(float(nested(sentinel1, "stats", "s1_vv_post_minus_pre_db_min")), 3)
    ae_mean = round(float(nested(alphaearth, "stats", "alphaearth_1_minus_cosine_mean")), 3)
    surface_label = (
        "strong_local_weak_mean"
        if s1_min <= -20.0 and abs(s1_mean) <= 0.1 and 0.5 <= dark_blue_pp <= 1.5 and ae_mean < 0.02
        else "mixed_surface_signal"
    )

    population = int(round(float(nested(worldpop, "population_sum", "population"))))
    receptor_threshold_hits = sum(
        [
            population >= 250000,
            osm["highway_count"] >= 300,
            osm["critical_amenity_count"] >= 20,
        ]
    )
    answer = "heavy_concentrated_rainfall_with_weak_mean_surface_change"

    primary_gt = {
        "answer": answer,
        "rain_window_days": days,
        "rain_threshold": {
            "products_ge_150": products_ge_150,
            "max_product_mm": round(maxima[max_product], 2),
            "pass": rain_threshold_pass,
        },
        "concentration": {
            "product": strongest_product,
            "max_to_mean_ratio": round(ratios[strongest_product], 3),
            "pass": concentration_pass,
        },
        "surface_contrast": {
            "sentinel1_mean_db": s1_mean,
            "sentinel1_min_db": s1_min,
            "dark_blue_pp": dark_blue_pp,
            "alphaearth_mean": ae_mean,
            "label": surface_label,
        },
        "receptor_ledger": {
            "population": population,
            "highways": osm["highway_count"],
            "critical_amenities": osm["critical_amenity_count"],
            "threshold_hits": receptor_threshold_hits,
        },
    }

    rubric = {
        "total_points": 20,
        "criteria": [
            {
                "name": "Output schema and label",
                "points": 3,
                "description": "Returns compact JSON with the requested fields and the final diagnostic label.",
                "partial_credit": "Award up to 2 points if the structure is mostly correct but one noncritical field is missing.",
            },
            {
                "name": "Rainfall load thresholds",
                "points": 4,
                "description": "Computes the 24-day window, 3 products at or above 150 mm, and 258.84 mm maximum.",
                "partial_credit": "Award 2 points for correct maxima without the threshold state.",
            },
            {
                "name": "Concentration ratio",
                "points": 4,
                "description": "Uses max divided by mean for each product and identifies GPM at 3.105 as the strongest ratio.",
                "partial_credit": "Award 2 points for a correct ratio but missing product name or threshold state.",
            },
            {
                "name": "Surface contrast",
                "points": 4,
                "description": "Uses Sentinel-1 mean and local minimum, dark-blue proxy increase, and annual embedding mean to assign strong_local_weak_mean.",
                "partial_credit": "Award 2 points if at least two of the four numeric inputs are correct.",
            },
            {
                "name": "Mapped receptor ledger",
                "points": 3,
                "description": "Computes 269933 population, 330 highway features, 20 critical amenities, and 3 threshold hits from declared package-relative WorldPop and OpenStreetMap derived statistics.",
                "partial_credit": "Award 1 point for any two correct receptor values.",
            },
            {
                "name": "Bounded numeric diagnosis",
                "points": 2,
                "description": "Keeps image proxies and receptor counts as numeric context rather than direct damage totals.",
                "partial_credit": "Award 1 point if the final label is correct but the bounds are only implicit.",
            },
        ],
    }

    key_values = {
        "event_window": {"start": start, "end": end, "days": days},
        "tolerances": {"mm": 0.02, "ratio": 0.005, "db": 0.01, "pp": 0.02, "population": 1},
        "formulas": {
            "duration_days": "inclusive calendar days from start to end",
            "max_to_mean_ratio": "product event-window local maximum / product event-window mean",
            "dark_blue_pp": "(event dark-blue proxy share - pre-event dark-blue proxy share) * 100",
            "receptor_threshold_hits": "count of population>=250000, highways>=300, critical_amenities>=20",
        },
        "precipitation_inputs": {
            "maxima_mm": {k: round(v, 3) for k, v in maxima.items()},
            "means_mm": {k: round(v, 3) for k, v in means.items()},
            "ratios": {k: round(v, 3) for k, v in ratios.items()},
            "three_product_mean_mm": round(three_product_mean, 3),
        },
        "threshold_results": {
            "rainfall_load_pass": rain_threshold_pass,
            "concentration_pass": concentration_pass,
            "surface_label": surface_label,
            "receptor_threshold_hits": receptor_threshold_hits,
        },
        "surface_inputs": {
            "sentinel1_pre_count": nested(sentinel1, "counts", "pre_count"),
            "sentinel1_post_count": nested(sentinel1, "counts", "post_count"),
            "sentinel1_mean_db": s1_mean,
            "sentinel1_min_db": s1_min,
            "dark_blue_pp": dark_blue_pp,
            "alphaearth_mean": ae_mean,
            "pre_image": pre_image,
            "event_image": event_image,
        },
        "receptor_inputs": {
            "population": population,
            "highways": osm["highway_count"],
            "critical_amenities": osm["critical_amenity_count"],
            "element_count": osm["element_count"],
            "amenity_counts": osm["amenity_counts"],
        },
    }

    return {
        "schema_version": "1.0",
        "task_id": TASK_ID,
        "event_id": event["package_id"],
        "task_type": "numeric",
        "target_family": "numeric_diagnosis",
        "evaluation_mode": "deterministic",
        "difficulty_level": "L3",
        "primary_gt": primary_gt,
        "event": {
            "package_id": event["package_id"],
            "event_name": event["event_name"],
            "hazard_family": event["hazard_family"],
            "event_date_or_window": f"{start} to {end}",
        },
        "deeper_objective": {
            "objective_type": "rainfall_concentration_surface_change_ledger",
            "description": "Compute a reproducible numeric ledger for rainfall load, rainfall concentration, surface-change contrast, and mapped receptor context.",
        },
        "key_values": key_values,
        "rubric": rubric,
        "provenance": {
            "computed_by": "compute_gt.py",
            "source_files": SOURCE_FILES,
            "notes": "All values are computed from local CSX-054 package files; receptor statistics are evaluated from declared package-relative WorldPop and OpenStreetMap derived fields.",
        },
    }


def main() -> None:
    result = build_result()
    apply_deepened_task_frame(result)
    output = json.dumps(result, indent=2, ensure_ascii=False)
    (TASK_DIR / "computed_gt.json").write_text(output + "\n", encoding="utf-8")


if __name__ == "__main__":
    main()
